quests[37832] = { id = 37832, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 009 - Forgotten Crab Trap" }
quests[37833] = { id = 37833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 010 - Offerings To Elune" }
quests[37834] = { id = 37834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orb of Dominion", description = "Gul'dan and his Shadow Council have their hooks embedded deep into Garona's soul. We've tried traditional magical methods and they haven't helped her. It's time to get unorthodox.\n\n<Khadgar cracks his knuckles, his eyes flashing with a disturbing eagerness.>\n\nI've just learned of a Shadow Council holdout hidden beneath the Draenei city of Elodor. They are using an Orb of Dominion to brainwash spies. Quickly! Assault the cave and recover the orb for me. We will turn this dark magic to our advantage.", progress = "<Khadgar's fingers glow in anticipation.>\n\nThe orb! Did you find it?", completion = "Hand it here - gently now - ah, do you feel it? Makes my skin crawl. It's watching us, {name}.\n\nI have invited the Shadow Council into my house. Let's get this over with before this thing can cause any mischief.", objectives = "Retrieve an Orb of Dominion from the Den of Secrets in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37835] = { id = 37835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow War", description = "The Shadow Council are more entrenched than you expected. A large contingent seems focused on infiltrating the draenei Exarch Council in the town above.\n\nKhadgar certainly wouldn't complain if you did a little... \"housecleaning.\"", completion = "Well done, {name}! I find it troubling that the Shadow Council is so entrenched in these hidden regions of Draenor. Gul'dan has kept himself busy.", objectives = "Slay 15 Shadow Council members in the Den of Secrets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37836] = { id = 37836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Badness", description = "It is time to liberate Garona. I know what to do... I think. I'd like you to stay close in case anything goes wrong.\n\nSpeak with me when you are ready to begin.", completion = "Garona remains shaken, but she is with us now. She is eager to plot revenge against her former master!\n\nI shall consider forgiving her for stabbing me.", objectives = "Speak with Khadgar and assist him as he frees Garona from Gul'dan's mind control.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37837] = { id = 37837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Inside Job", description = "If Garona's intelligence is correct, Gul'dan will be inside this Iron Horde compound. With Garona's help, slip inside, gather any info you find, and learn what Gul'dan intends to do.\n\nThe guards are on high alert. Garona can \"liquidate\" individual guards for you, but she must not be seen! You will have to choose your targets carefully and pick your way through the bastion undetected. Don't let anyone sound the alarm.\n\nIf things get too hot, I'll teleport you to safety. At least... I'll try.", progress = "Don't give up. I know you can do this.\n\n<Despite his words, Khadgar doesn't seem so sure.>", completion = "Well done, both of you!\n\nGul'dan is even more slippery than I imagined. He's been building up his power base behind the scenes, and now that we've weakened his foes, he's moved in to take control of what remains of the Iron Horde.\n\nWe need to plan our next move.", objectives = "Infiltrate Bladefury's Command with Garona's help. Use her talents to eliminate guards without being seen. Locate Iron Horde intelligence and then spy on Gul'dan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37838] = { id = 37838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Garona", objectives = "{class}, I know that I have done little to earn your trust. Until you freed me, my life was not my own.\n\nYour tenacity, and the wisdom of your Archmage, have finally set me free. You had faith in me even when I had no faith in myself. You have given me back my life, and now I freely pledge it to you. I will serve you here on Draenor until my dying day.\n\nPoint me at your enemies, and I will deliver unto them a swift and silent end... Commander.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37839] = { id = 37839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light Be With You", description = "You've done everything I've asked, {name}. I believe we can apply one final enchantment to your ring. But... we must be cautious. Last time I augmented your ring I killed you. (Sorry.) It will take a divine act to empower you further.\n\nFortunately, you've made some powerful allies during your time here. Travel to the Temple of Karabor, where Yrel is waiting for you. With the blessing of a Naaru your ring will become as powerful and unique as - well, as you yourself. Go to Karabor. You've earned it.", completion = "You have earned this, {class}. You've traveled the length and breadth of my world. You've surmounted unimaginable odds and stood toe-to-toe against ancient beasts, dark magics, and terrifying machines. Time and again you've inspired my people with your patience and bravery.\n\nThank you, {name}.", objectives = "Meet Yrel at the Coliseum of Light near the Temple of Karabor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37840] = { id = 37840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draenor's Blessing", description = "You've done everything I've asked, {name}. I believe we can apply one final enchantment to your ring. But... we must be cautious. Last time I augmented your ring I killed you. (Sorry.) It will take an act of ancient magic to empower you further.\n\nFortunately, you've made some powerful allies during your time here. Seek out Farseer Drek'Thar at the Throne of Elements in Nagrand. There you can receive the blessing of the elements and safely unlock your ring's final form. Go, hero! Claim your reward!", progress = "More than any other you embody the might of the Horde, champion.", completion = "You have earned this, {class}. You've traveled the length and breadth of this savage world. You've surmounted unimaginable odds and stood toe-to-toe against ancient beasts, dark magics, and terrifying machines. Time and again you've surprised me with your patience and bravery.\n\nThank you, {name}. I am proud to call you my friend.", objectives = "Speak with Drek'Thar at the Throne of the Elements in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37841] = { id = 37841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Assault", description = "Our campaign in Draenor has taken an unexpected turn. With Gul'dan assuming power over the Iron Horde, history is poised to repeat itself - our world is in more peril than ever.\n\nIt's time to bring the full might of your garrison to bear against Tanaan Jungle. Build a shipyard for your garrison! I will meet you at your new shipyard and we will discuss our next move from there.", completion = "We meet again.\n\nNow that you have a shipyard, let's talk about next steps...", objectives = "Speak with your faction leader in your garrison and complete the quests to build a shipyard. Khadgar will meet you there when it's built.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37842] = { id = 37842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Yaeger-367" }
quests[37843] = { id = 37843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mana Bark", description = "We need bark from the trees if we are going to fix the wood.\n\nBeing a mortal, you can walk right in and pick up the mana bark without any trouble, as long as you don't get eaten by something.\n\nCan you get us some mana bark?", objectives = "Collect 8 Mana Bark.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37844] = { id = 37844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essence of the Unbound", description = "I need your help, mortal.\n\nSomething has warded the Mana Wood against our kind\n\nThat same something is changing the song of the wood. We can hear it.\n\nEnter the wood and gather essence from some of the local wildlife and maybe we can track this thing down.\n\nI will project an image of myself in the wood for when you are done.", objectives = "Collect 20 Unbound Essences.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37845] = { id = 37845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rift Rippers", description = "Something is opening rifts to the twisting nether using the ley line energy.\n\nThat is never a good thing.\n\nOur kind may not be able to enter the forest, but you can.\n\nTake this gem and look for these unbound rifts. The gem will let you seal these breaches.\n\nI will project an image of myself into the forest when you are done.", objectives = "Seal 3 Unbound Rifts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37848] = { id = 37848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure Contract: Amulet of Rukhmar", description = "It seems the Adherents of Rukhmar have stumbled upon some information leading to an ancient amulet, said to possess the power of their god and bestow it upon the wearer. We should make sure they don't find it.\n\nHead to Skettis and find what they have learned. Hopefully we can find it before they get to it.", objectives = "Search the ruins of upper Skettis for the Arakkoa research involving the Amulet of Rukhmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37849] = { id = 37849, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amulet of Rukhmar: The First Key", description = "The Arakkoa research points to three \"keys\" that need to be activated in order to use the Apexis device. The first is located in Skettis. The text mentioning it reads:\n\n\"The first key is kept in the high reaches of upper Skettis. It lay where the dead can protect it from the talons of the unwanted.\"", objectives = "Find and activate the first key to the Apexis device.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37850] = { id = 37850, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amulet of Rukhmar: The Second Key", description = "The first point has been activated and two more remain. The second location is hinted at in the old outcast writing:\n\n\"Beneath the third fall of the great Skettis river lay the second key. May the ever-rushing waters sweep away those that might seek it.\"", objectives = "Find and activate the second key to the Apexis device.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37851] = { id = 37851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amulet of Rukhmar: The Final Key", description = "One last key is required to access the Apexis device. The writings pertaining to its location read:\n\n\"The final key has been housed deep within the fungal caves where the river makes its final drop. Though the pale orcs that dwell there may be vile, they should prove a worthy deterrent.\"", objectives = "Find and activate the final key to the Apexis device.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37852] = { id = 37852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amulet of Rukhmar: The Apexis Device", description = "Now that the keys have been activated, the Apexis device that leads to the amulet should be accessible. \n\nThe Arakkoa research states that it is likely located in Lost Veil Anzu, within the \"shrine to the raven god.\"", progress = "Were you able to take the amulet from the arakkoa?", completion = "I'm glad to see this out of the claws of the Adherents of Rukhmar. \n\nI'll get this to Dr. Jones right away.", objectives = "Activate the Apexis device and claim the Amulet of Rukhmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37853] = { id = 37853, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Death of the Eldest", description = "I will do what I can to stabilize him, but I will need your help.\n\nThe small amount of energy he has left is coming from the mana pool he rests in.\n\nFollow the whelplings' lead. Dropping ley crystals into the pool gives him a bit of energy - buying him a few more breaths.\n\nThey seem to be getting the crystals from inside that cave to the north.", progress = "Call me a fool. I'd always just thought that grandfather would be with us forever.", completion = "Thank you. Your efforts dull his pain.\n\n<She sighs.>", objectives = "Slay Leyworms to obtain 6 Crackling Leyworm Cores, then drop them into Senegos's pool.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37855] = { id = 37855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last of the Last", description = "We need help.\n\nSince the fall of Deathwing, we dragons have lost nearly all of our power. To make matters worse, we can no longer bear eggs.\n\nMy whelplings are the last of the last.\n\nI need you, champion. Help defend my whelplands, and I swear to you, the blues will be at your side when you need them.", completion = "Don't you worry, small one. I am still back in Azurewing Repose, resting in my pool.\n\nIt doesn't take much energy to throw a projection of myself here and there. I may be old and dying, but I AM still a blue dragon.", objectives = "Investigate the Azurewing Whelplands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37856] = { id = 37856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Withered", description = "The withered are the worst kind of pest. They capture our whelplings, knock them unconscious, and then drink whatever mana they can from the helpless babes.\n\nNormally our drakes and keepers would fend them off. Today, it looks like we may need your help.", progress = "Yes?", completion = "Twelve withered slain? Very good.\n\nThat should be enough to keep them away for a few months.", objectives = "Slay 12 withered in the Azurewing Whelplands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37857] = { id = 37857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runas Knows the Way", description = "I wish to make it up to you for whatever I did that made you want to kill me.\n\nHmm... your dragon complains about being weak. I know why. Runas can fix it, my friend.\n\nOne of my kind, Ael'Yith, pulls ley energy from the very ground of Azsuna. I can take you to the location of his mana siphons.\n\nIt's not too late to undo the harm the others have done. You've done well to trust me.", progress = "I still don't trust him.", completion = "They're tapping into the ley lines?", objectives = "Allow Runas to escort you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37858] = { id = 37858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stellagosa", description = "Something is wrong, {name}.\n\nI sent Stellagosa to assist you, but I can no longer sense her.\n\nPlease, go out there and find out what's happened to my granddaughter.", completion = "...so many of them...", objectives = "Find Stellagosa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37859] = { id = 37859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Consumed", description = "<The whelpling is alive, but unconscious. One of the withered must have already drained it of mana.>\n\n<You've already learned that exposed ley crystals contain a small amount of magical energy. Perhaps you can use one to revive some of the whelps.>", progress = "Clever {race}. Yes, a ley crystal should bring them back to their senses.", completion = "I owe you a great debt, {name}.\n\nHelping a weakened old dragon like me is valorous enough. Saving my whelplings, and securing the future of our bloodline?\n\nI am now firmly committed to your cause.", objectives = "Find a Dim Ley Crystal, then revive 10 Mana-Drained Whelplings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37860] = { id = 37860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Scratch My Back...", description = "Much better. I knew I could count on you, my friend. Allow me to return the favor.\n\nI know how you can destroy the large mana collector pylons. We shall save your dragon yet!\n\nThe pylons only work against ground targets, yet they're defenseless from above. Send your whelplings at them, my friend. The whelplings can fly where we cannot.\n\nTrust me.", completion = "With the pylons destroyed, Senegos' pool should now be re-energized.", objectives = "Release the whelplings on each of the Mana Collector Pylons in Zarkhenar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37861] = { id = 37861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nightborne Prince", description = "<Senegos is focused.>\n\nI sense it now. In the ruined building, to the east. One of these cretins must have tapped deep into the ley line.\n\nI suspect he will be heavily defended, {name}. Once again, the well-being of my brood is in your hands.", completion = "He may not be slain, but at least he is gone.\n\nWithout their leader, the mindless withered should soon scatter and die.", objectives = "Slay Ael'Yith.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37862] = { id = 37862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Still Alive", description = "Wait, what was it that I heard? Was it... \"feast on the dragons\"? We must check on grandfather, right away!\n\nLet me know when you're ready to depart.", completion = "No... we're too late!", objectives = "Speak with Stellagosa to take a ride back to Azurewing Repose.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37864] = { id = 37864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voidtalon of the Dark Star" }
quests[37865] = { id = 37865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Ironhold Harbor" }
quests[37866] = { id = 37866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Ironhold Harbor" }
quests[37867] = { id = 37867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystalbeard" }
quests[37868] = { id = 37868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Big Racing!", description = "You like this big race, do you? Me too!\n\nIt has four legs: get to the purple post, then green, then red, then back here.\n\nYour time matters, so do it fast!", progress = "You haven't hit all the markers. Hurry!", completion = "Good job, and nice time!", objectives = "Run through the Start Banner, hit the Purple Post, then the Green Post, then the Red Post, then the  return to the Start Banner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37869] = { id = 37869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daggerbeak" }
quests[37881] = { id = 37881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure Contract: Explosive Discoveries", description = "In Shadowmoon Valley there is a cave said to possess an ancient tome that may contain secrets that can help our cause against the Iron Horde. The cave, however, is protected by an ancient barrier composed of arcane energy.\n\nThere is a goblin in Darktide Roost, said to know how to take down any barrier. Persuade him to give up his secrets and bring back the book.", objectives = "Defeat Demolitionist Megacharge in Darktide Roost and take his explosives cookbook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37882] = { id = 37882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Grimoire: The First Ingredient", description = "You will need three ingredients to make Megacharge's special \"Arcane Bunker Buster,\" which should be able to take down the barrier. The first ingredient, some precision blasting powder, should be available nearby. The book reads:\n\n\"To make one, you'll first need to acquire some high grade, precision blasting powder. Here in Blackfuse Company, it's pretty easy to come by, since they use it for all of the cannons.\"", objectives = "Follow the clue from Megacharge's Cookbook to locate some precision blasting powder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37883] = { id = 37883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Grimoire: The Second Ingredient", description = "With the blasting powder acquired, you now must find a suitable detonator. A note attached to the entry in the cookbook hints to where one might be found:\n\n\"Reminder: Order more high-voltage detonators. The last shipment was lost off of the Shadowmoon coast near the demon-inhabited cliffs. Maybe we should send a diving team to salvage.\"", objectives = "Follow the clue from Megacharge's Cookbook to find the high voltage detonator.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37884] = { id = 37884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Grimoire: The Final Ingredient", description = "The final ingredient to create Megacharge's bomb is a sizable quantity of demon's blood. \n\nUnfortunately, that's not something they're likely to give up easily...", objectives = "Collect blood from demons in Socrethar's Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37885] = { id = 37885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Grimoire: Breaching the Barrier", description = "The components have been gathered and the \"Arcane Bunker Buster\" is assembled. Hopefully, this should pack enough punch to take out the barrier.\n\nThere's only one way to find out...", progress = "Dr. Jones asked me to take this book from you, but I'm not sure I want to touch it.", completion = "I'll make sure this gets to Dr. Jones. \n\nTo be honest, I'm eager to get it off my hands.", objectives = "Destroy the ancient barrier below Socrethar's Rise and claim the Grimoire of the Nameless Void.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37886] = { id = 37886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Max-level Choice Tracker: Tanaan 6.2 - Ironhold" }
quests[37887] = { id = 37887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanaan Garrison Max-level Choice Tracker: ANY CHOICE MADE" }
quests[37888] = { id = 37888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "6.2 Tanaan Max-level Choice Reward Summary: Solo" }
quests[37889] = { id = 37889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Invasion of Tanaan", description = "It is done! By your command we have built our first ship and can run our naval operations from here.\n\nNow that we have our transport, we can let Durotan and that Archmage of yours know that we are ready to kick off an invasion of Tanaan. Speak with them at the docks to embark.", completion = "The landing was easier than I expected, but there is trouble ahead.", objectives = "Meet with Khadgar and then speak to Draka to start the invasion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37890] = { id = 37890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Obstacle Course", description = "It is strange that these docks were abandoned by the Iron Horde, but up ahead our scouts report trouble.\n\nA set of Bleeding Hollow scavengers is busy looting the abandoned buildings to the northwest.\n\nFurther down the road orc cultists are doing... something... near the Dark Portal.\n\nWe should try to recover any orders or information as to what is going on here, then meet with our scouts further in...", completion = "It be good ta hear da road is safer, but here be another problem.", objectives = "Find any information on the forces deployed in the area and meet with the scouts afterwards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37891] = { id = 37891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Ironhold Harbor", description = "The Iron Horde continue to bring in reinforcements from all over Draenor to reinforce their position at Hellfire Citadel. If we don't cut off the flow of supplies then we risk losing control of our plans in Tanaan.\n\nA strategic attack to the supply lines at Ironhold Harbor is just the thing to keep the Iron Horde on the defensive and maintain our momentum.", completion = "Welcome back, commander. Our scouts just returned with word of your success.\n\nWell done!", objectives = "Assault the Iron Horde reinforcements at Ironhold Harbor in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37892] = { id = 37892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanaan Garrison Max-level Choice Tracker: ANY CHOICE MADE" }
quests[37908] = { id = 37908, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inquisitor Ernstenbok" }
quests[37909] = { id = 37909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warbringer Mox'na" }
quests[37910] = { id = 37910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Real Race", description = "Ok, Darkmoon Racer, let's see what you got!\n\nThe real race has four legs: get to the blue post, then green, then red, then back here. \n\nYour time matters, so do it fast!", progress = "You haven't hit all the markers. Hurry!", completion = "Good job, and nice time!", objectives = "Run through the Start Banner, hit the Blue Post, then the Green Post, then the Red Post, then return to the Start Banner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37911] = { id = 37911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Real Big Race", description = "Here's the big one! Good luck out there!\n\nThis race has four legs: get to the purple post, then green, then red, then back here. \n\nYour time matters, so do it fast!", progress = "You haven't hit all the markers. Hurry!", completion = "Good job, and nice time!", objectives = "Run through the Start Banner, hit the Purple Post, then the Green Post, then the Red Post, then the  return to the Start Banner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37914] = { id = 37914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure Contract: The Thunderlord Sage", description = "In Frostfire Ridge, a Thunderlord sage by the name of Argoram seems to have uncovered the whereabouts of a storied weapon, known to the orcs as Gronnsbane. \n\nHe was last spotted headed into Magnarok. Find him and see if he can lead you to this relic.", objectives = "Locate the Thunderlord sage Argoram in Magnarok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37916] = { id = 37916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gronnsbane: The Broken Spear", description = "Looking through Argoram's journal, it becomes apparent that claiming this relic will be far more complicated than simply finding the pieces of the spear.\n\nHowever, that would be the best place to start...", objectives = "Search throughout Magnarok for Gronnsbane's blade, haft, and weight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37917] = { id = 37917, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gronnsbane: The Blessing of Fire", description = "The weapon has been assembled, but it lacks the power that made it a legend. In order to restore it, you must receive three blessings: one of fire, one of frost, and one of beasts.\n\nThe first blessing mentioned in the journal is that of fire. The journal reads:\n\n\"He describes an ancient monolith, perched upon the edge of a precipice extending from the cliff where the searing magma falls into the sea.  I believe the location he speaks of is just overlooking Tor'goroth's Tooth.\"", objectives = "Follow the clue to find the Molten Shamanstone and receive the Blessing of Fire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37918] = { id = 37918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gronnsbane: The Blessing of Frost", description = "The weapon has been imbued with the Blessing of Fire, drawing power from the Molten Shamanstone. The Frozen Shamanstone should impart the next blessing. Argoram mentions its location in his journal:\n\n\"As I was maneuvering away from the great boulders hurled at me by the ogron brutes, I glanced what looked like another monolith atop the tallest of the snow-capped towers in Bloodmaul. Perhaps this is the Frozen Shamanstone, which is thought to grant the Blessing of Frost\"", objectives = "Follow the clue to find the Frozen Shamanstone and receive the Blessing of Frost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37919] = { id = 37919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gronnsbane: The Blessing of Beasts", description = "Gronnsbane now pulses with energies of fire and frost. All that remains to restore the full power of the weapon is to receive the Blessing of the Beast. Argoram believed this could be accomplished by bloodying the weapon against one of the ancient black rylaks of Stonefury Cliffs. His journal reads:\n\n\"High in the Stonefury Cliffs, I have seen an altar where the ogres have left offerings to these ancient beasts. Perhaps I could use it to lure one of them\"", progress = "Have you returned with the Thunderlords' relic?", completion = "Who would've thought that such a normal looking spear would be able to take down a full-sized Gronn? \n\nI'm sure Dr. Jones will appreciate this in his collection.", objectives = "Defeat the ancient black rylak and douse Gronnsbane in its blood.\n\nOnce empowered, return the weapon to Bodrick Grey for your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37921] = { id = 37921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Docks", description = "Our salvage team thought these here docks would be abandoned, but they're crawlin' wit' remnants of the Iron Horde. Gul'dan's cronies are convertin' anyone they can and evacuatin' everyone to Tanaan Jungle.\n\nCommander, if yeh can clear this place out, my team can salvage some of this equipment.\n\nPlus, ev'ry orc yeh kill here is one less ta worry about in Tanaan!", objectives = "Kill 1 Iron Horde orcs and 50 ogron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37924] = { id = 37924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maritime Salvage", description = "It would go a bit faster if you could mark any bigger piles of resources you see while you are clearing those guys out.\n\nJust drop this flag down and someone will be along directly!", objectives = "Mark 7 supply caches with flags.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37927] = { id = 37927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Meet at Light's Hope", description = "Thank the Light I found you!\n\nHighlord Fordring has called all paladins to Light's Hope Chapel to discuss our next course of action following the Broken Shore. He sent me to personally make sure you were in attendance.\n\nI will ask Khadgar to direct this portal to Light's Hope for you. We must make haste.", objectives = "Enter the portal to Light's Hope Chapel and speak to Tirion Fordring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37928] = { id = 37928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Normantis the Deposed" }
quests[37930] = { id = 37930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whelp? That Happened.", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37932] = { id = 37932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbound Rift" }
quests[37933] = { id = 37933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uncovering the Artifact Fragments", description = "The Artifact Fragments seem to come from any creature we've found in the outskirts of Ashran. Go out and kill any you find and bring at least five to Ecilam the Mage near the campfire in Stormshield Stronghold.", sourceObjective = "Harrison Jones in Stormshield Stronghold wants you to go kill creatures in the outskirts of Ashran outside of the main road and bring back 5 Artifact Fragments to Ecilam.", sourceObjectiveStatus = "unverified-source-field" }
quests[37934] = { id = 37934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In, Through, and Beyond!", description = "A few of us snuck through before we was spotted, den de cannons started up. De small ones are no trouble, but de big one... we gonna need to take it out if we wanna get anyting through.", completion = "We be movin' supplies through here now. We finda good place to build!", objectives = "Destroy the Fel Defense Cannon covering the gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37935] = { id = 37935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Assault Base", description = "Nearby be a good place. Not too close to da enemy, but close enough for us to take some pressure off da boys in the west. Follow me.", completion = "The easy part is done, now comes the hard part.", objectives = "Establish your assault base in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37937] = { id = 37937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Varyx the Damned" }
quests[37938] = { id = 37938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Ruins of Kra'nak" }
quests[37939] = { id = 37939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Max-level Choice Tracker: Tanaan 6.2 - Ruins of Kra'nak" }
quests[37940] = { id = 37940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Ironhold Harbor", description = "The Iron Horde continues to bring in reinforcements from all over Draenor to reinforce their position at Hellfire Citadel. If we don't cut off the flow of supplies then we risk losing control of our plans in Tanaan.\n\nA strategic attack to the supply lines at Ironhold Harbor is just the thing to keep the Iron Horde on the defensive and maintain our momentum.", completion = "Word of your success has already been passed on by our scouts. \n\nLok'tar!", objectives = "Assault the Iron Horde reinforcements at Ironhold Harbor in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37941] = { id = 37941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure Contract: The Infected Orc", description = "In Gorgrond, the Laughing Skull clan has a legend of one called Skulltaker. His mask, known only as the Silent Skull, is legendary among the clan, and could help us learn more about them.\n\nUntil recently, he was thought to have vanished. Now it appears he has shown his face, so to speak, in Everbloom Wilds. The last orc to have seen him fell to the botani there, but may still have some clues on how you can find Skulltaker and recover the mask.\n\nIf the botani have him, he may not be cooperative.", objectives = "Find Grinning Tolg's journal among the mutated orcs in Everbloom Wilds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37942] = { id = 37942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Silent Skull: The First Reagent", description = "Grinning Tolg was in the process of brewing an elixir that would allow him to communicate with the ravagers, whom the Skulltaker relies on to remain hidden.\n\nThe first ingredient, the leaves of the Shadethistle plant, can be found nearby. The journal reads:\n\n\"It rests in the shadows of the harsh Gorgrond sun. I saw some under standing stones near the black iron walls.\"", objectives = "Follow the clue from the journal to find the Shadethisle Leaves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37943] = { id = 37943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Silent Skull: The Second Reagent", description = "The second ingredient to the elixir is a vine from the Bonethorn plant. The journal reads:\n\n\"I must find a vine of bonethorn, which grows in the bones of the ancient dead. I remember seeing the bones of a long-dead beast in the dry beds of the northern wilds. Its sun-parched skull would make a pleasant home for such a plant.\"", objectives = "Follow the clue from the journal to find the Bonethorn Vine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37944] = { id = 37944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Silent Skull: The Third Reagent", description = "The final component of the elixir is a handful of Steamcap mushrooms. The journal reads:\n\n\"The Crowfeeder said that they grow among the steam vents in the higher parts of the Everbloom. I have seen one such place above the northern hydra pools.\"", objectives = "Follow the clue from the journal to find the Steamcap Mushrooms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37945] = { id = 37945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Silent Skull: Taking from the Taker", description = "With the reagents found, you should seek out Grinning Tolg's camp in the nearby cave to brew the elixir. \n\nOnce the elixir is consumed, you should be able to communicate with the ravagers there. With any luck, they should be able to bring you to Skulltaker.\n\nHis mask should bring a hefty reward.", progress = "This must be the cursed skull. Are you sure we should be touching it?", completion = "This definitely looks like no Laughing Skull mask I've seen before. I'll take it to Jones and see what he makes of it. \n\nHe left me with this payment for you.", objectives = "Use the Laughing Skull elixir to find Skulltaker and claim the Silent Skull.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37946] = { id = 37946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Max-level Choice Tracker: Tanaan 6.2 - Ironhold" }
quests[37947] = { id = 37947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "6.2 Tanaan Max-level Choice Reward Summary: Solo" }
quests[37948] = { id = 37948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to Nullifier Darkoor!", description = "Gurgthock stopped by from the Ring of Blood and said that Mogor wants his Blood Champion to participate in a special exhibition match. That's you, commander!\n\nJust whisper \"I seek the seeker.\" into Gurgthock's ear and he'll get things going for ya!", completion = "Word is already spreading of your epic fight, commander. This may improve relations with the ogres in the future.", objectives = "Speak to Gurgthock at the Ring of Blood in Nagrand and win the special exhibition match.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37949] = { id = 37949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to Nullifier Darkoor!", description = "Da goblin Gurgthock stopped by and be sayin' that Mogor wants his Blood Champion to fight in an exhibition match against something terrible he's dug up. Dat be you, boss.\n\nIf you be ready, whisper to Gurgthock \"I seek da seeker.\" He take care of da rest.", completion = "Word already be spreadin' about your exploits. If da ogres did not fear your strength yet, dey should now.", objectives = "Speak to Gurgthock at the Ring of Blood in Nagrand and win the special exhibition match.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37953] = { id = 37953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Sergeant Mor'grak" }
quests[37956] = { id = 37956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Netherstruck Charm" }
quests[37957] = { id = 37957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runas the Shamed", description = "I fell so quickly, {name}. I am not as strong as I once was. We truly do need your help.\n\nOne of these disgusting creatures ran off with several of the whelplings. I heard him called by name:\n\nRunas.\n\nI will survive. Home is not far. You still have strength, though. Slay this Runas before he does any more damage to our brood.", progress = "Ah, Stella. Always so quick to act. She is still young.", completion = "Keep your distance from that one, {name}.\n\nThose fallen elves are all the same. As two-faced as they come.", objectives = "Slay Runas the Shamed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37958] = { id = 37958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 011 - Nether Crystal" }
quests[37959] = { id = 37959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunger Returns", description = "<Runas looks antsy.>\n\nI can help you, and I very much want to help you, but I'm a bit distracted. Look at all that raw, unfiltered, mouthwatering mana...\n\n<Runas slaps his own face.>\n\nNo! NO! You must stay in control!\n\nI simply need to clear my head. Yes, that's it. A few of my depraved brethren carry small mana jewels around with them in case they need a quick burst of energy. Find a few for me? Then I will show you how to get your ley line back.", progress = "Do you have them? Please tell me you have them, my friend.", completion = "<Runas feverishly crushes the jewels and gets to work rubbing magical dust on his face, arms, and back.>\n\n<He is, for the moment, in bliss.>", objectives = "Obtain 4 Charged Mana Jewels.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37960] = { id = 37960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leyline Abuse", description = "These monsters are pulling mana directly out of the ground. This explains why not even my mana pools can dull my pain.\n\nI worry about my brood. Without the power of the ley lines, we are nothing. At this rate, I may not even be able to help you with your Tidestone.\n\nLook for their mana siphons, and punish the cowardly nightfallen elves that are using them.", progress = "With each one of these cretins you slay, I grow stronger.", completion = "I do feel a bit stronger.\n\nThose siphons nearly did me in, {name}.", objectives = "Slay Iskhaneth and Tyndrissen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37961] = { id = 37961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringing the Bass", description = "You know what would boost morale around here?\n\nBass. Beats. Music!\n\nEveryone loves a party! You go out and get me some hardware, and I'll make a system that will shatter Draenor itself.", progress = "Collect a Bass Blaster, Laz-Tron Disc Reader, Phonic Amplifier, S.P.R.K. Capacitor, and a Cord of Ancient Wood.", completion = "What great shape this stuff is in. Yeah, honest! I think I can work with this junk. Give me just a minute here..." }
quests[37962] = { id = 37962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[37963] = { id = 37963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Those Beyond Redemption" }
quests[37964] = { id = 37964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Gul'dan!", description = "We must act quickly - Garona here tells me that Gul'dan is on the move. He is headed to the Path of Glory to meet with Grommash Hellscream.\n\nWe have to act while our intelligence is fresh! Hurry and meet us outside of Bladefury's Command in northern Talador. We won't be able to engage Gul'dan and the whole Iron Horde army on our own, but we may just learn something to use against them...", completion = "This place is absolutely crawling with guards. I don't know how Garona can be so confident.\n\nAh well, let me brief you on the plan, such as it is...", objectives = "Speak with Archmage Khadgar outside of Bladefury's Command in Northern Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37965] = { id = 37965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tainted Vintage" }
quests[37966] = { id = 37966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Temple of Sha'naar" }
quests[37967] = { id = 37967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Max-level Choice Tracker: Tanaan 6.2 - Temple of Sha'naar" }
quests[37968] = { id = 37968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Temple of Sha'naar", description = "Up in the hills of Tanaan Jungle, the Sargerei have converted a once-sacred temple into a den of demonic summoning.\n\nWe must attack them now, before their rituals complete. The longer we delay, the stronger our enemy grows.", progress = "How goes the attack, sir?", completion = "Welcome back, commander. Our scouts just returned with word of your success.\n\nWell done!", objectives = "Assault the Sargerei forces at the Temple of Sha'naar in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37969] = { id = 37969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanaan Jungle - Tracking Quest - Vol'mar Built - JMC" }
quests[37970] = { id = 37970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Fel Forge", description = "The Iron Horde continue to bring in reinforcements from all over Draenor to reinforce their position at Hellfire Citadel. If we don't cut off the flow of supplies then we risk losing control of our plans in Tanaan.\n\nA strategic attack to the supply lines at Ironhold Harbor is just the thing to keep the Iron Horde on the defensive and maintain our momentum.", objectives = "Assault the Iron Horde reinforcements at Ironhold Harbor in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37972] = { id = 37972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pet Battles Not Active" }
quests[37973] = { id = 37973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure Contract: The Artificer", description = "I have heard of a draenei artificer by the name of Maatun that was seeking to restore an old draenei crystal, possibly of naaru origin. He called the crystal the Dream of Argus. \n\nThe draenei went missing after seeking out help from the Shadowmoon orcs back before they allied themselves with the Iron Horde. One of your scouts recently spotted a draenei matching the description of Maatun near the entrance of the Pillars of Fate. Go there and see what you can dig up.", objectives = "Search near the entrance of the Pillars of Fate for evidence of Artificer Maatun's crystal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37974] = { id = 37974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pet Battles Not Active" }
quests[37975] = { id = 37975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pet Battles Not Active" }
quests[37976] = { id = 37976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dream of Argus: The First Fragment", description = "In his quest to restore the Dream of Argus, Maatun enlisted the help of three orcs. These same orcs betrayed him and took the crystal shards before they could be combined. If you find these orcs, they may still have them.\n\nThe first target shouldn't be far. The journal reads:\n\n\"I was told she spent most of her time in the crystal cave to the north of the encampment. There she studied the native crystals for ways to improve their potential abilities.\"", objectives = "Follow the clue from the journal to find Lor Stonefist. Defeat her and claim the Rough Crystal Shard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37977] = { id = 37977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dream of Argus: The Second Fragment", description = "The second orc that Matuun mentioned was a master runecarver and sorcerer. He should be located somewhere in the main camp. The journal reads:\n\n\"She mentioned that the orc could normally found in one of the runemaster's huts in the southern part of the camp. They could be identified by the standing stones surrounding the structure, as well as the floating runestones above.\"", objectives = "Follow the clue in the journal to find Vok Blacktongue. Defeat him and claim the Cracked Crystal Shard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37978] = { id = 37978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dream of Argus: The Final Fragment", description = "The last orc to be found was a hermit who kept away from the bulk of the Shadowmoon orcs at the Pillars of Fate camp, but was often seen in the high hills above. The journal reads:\n\n\"It is said, however, that he can often be seen among the graves upon the high hill, overlooking the camp below.  There he would commune with the dead ancestors, whom it is said he preferred over his living brethren.\"", objectives = "Follow the clue in the journal to find Koros Soulsplinter. Defeat him and claim the Smooth Crystal Shard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37979] = { id = 37979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dream of Argus: The Crystal Reborn", description = "With the shards recovered, it is now possible to restore the Dream of Argus. You must seek out the device that Maatun mentions in his journal, which is said to be in a cave overlooking Anguish Fortress.", progress = "Were you able to restore the draenei crystal?", completion = "This is incredible! I would never be able to tell that this crystal was once broken! \n\nI'm sure Dr. Jones will be pleased to see this, as well as the draenei if the stories behind it are true.", objectives = "Locate the crystal reconstruction device and use it to restore the Dream of Argus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37980] = { id = 37980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 012 - Book Treasure" }
quests[37981] = { id = 37981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The World Famous Ring of Blood!", description = "Dear Unadulterated Badass,\n\nIf you're reading this, you're exactly the sort of tough-as-nails champ in the making we need down at the Ring of Blood in Nagrand.\n\nYou and two friends are cordially invited to fight for your lives against the toughest creatures this side of Gorgrond. It's positively brutal - and the crowd loves it!\n\nCome talk to me to start your first fight - beat four of the fiercest creatures I've got and you'll get a shot at the champ himself!\n\n-Gurgthock", progress = "Two hundred gold... two hundred and fifty...\n\nThat makes it about three fifty. Not bad!\n\nOh, hey, what's shakin' champ?", completion = "You did it. You really did it! Here's your winnings, champ.\n\nMan, the Highmaul ogres are not going to like this...", objectives = "Become Lord of the Ring at the Ring of Blood in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37982] = { id = 37982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Art Tracker - Ashbringer - Tier 0 - Base" }
