quests[37990] = { id = 37990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Cindral" }
quests[37991] = { id = 37991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agapanthus", description = "<This whelpling is trying to get your attention. She locks eyes with you, then quickly flicks her head toward the northeast.>", completion = "Hail, {class}. We could use your aid.", objectives = "Investigate and assist the visitors in Azurewing Repose.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37992] = { id = 37992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gutrek's Cleaver: The Spirit Forge", description = "With the pieces recovered, all that is left is to reforge Gutrek's Cleaver. Goldspade's journal seems to indicate that the only place to do this is the location where it was initially dismantled.\n\nThe journal mentions a \"Spirit Forge\" used to dismantle the blade, and that it may be located somewhere in the nearby gorge. Find the forge and use it to combine the pieces you've gathered.", progress = "Dis be da blade dat Jones was lookin for?", completion = "Excellent, mon! I be takin dis to Jones right away. \n\nHere be your reward.", objectives = "Locate the Spirit Forge in Earthshaker Gorge and reforge Gutrek's Cleaver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37993] = { id = 37993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amulet of Rukhmar: The Apexis Device", description = "Now that the keys have been activated, the Apexis device that leads to the amulet should be accessible. \n\nThe Arakkoa research states that it is likely located in Lost Veil Anzu, within the \"shrine to the raven god.\"", progress = "Ya manage ta get da amulet?", completion = "It's good we got dis and not da arakkoa.\n\nJones will be wantin dis, I'm sure.", objectives = "Activate the Apexis device and claim the Amulet of Rukhmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37994] = { id = 37994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Grimoire: Breaching the Barrier", description = "The components have been gathered and the \"Arcane Bunker Buster\" is assembled. Hopefully, this should pack enough punch to take out the barrier.\n\nThere's only one way to find out...", progress = "I can sense a bad voodoo comin from ya, mon. \n\nDat be da book I'm feelin?", completion = "Dis book be a bad ting, mon. I'm glad we got it before it came into da wrong hands. \n\nI'll get it ta Jones for ya.", objectives = "Destroy the ancient barrier below Socrethar's Rise and claim the Grimoire of the Nameless Void.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37995] = { id = 37995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gronnsbane: The Blessing of Beasts", description = "Gronnsbane now pulses with energies of fire and frost. All that remains to restore the full power of the weapon is to receive the Blessing of the Beast. Argoram believed this could be accomplished by bloodying the weapon against one of the ancient black rylaks of Stonefury Cliffs. His journal reads:\n\n\"High in the Stonefury Cliffs, I have seen an altar where the ogres have left offerings to these ancient beasts. Perhaps I could use it to lure one of them\"", progress = "You bring da spear from da Thunderlords?", completion = "Jones will be happy when he sees dis. \n\nHere's da payment he promised.", objectives = "Defeat the ancient black rylak and douse Gronnsbane in its blood.\n\nOnce empowered, return the weapon to Rokhan for your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37996] = { id = 37996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Silent Skull: Taking from the Taker", description = "With the reagents found, you should seek out Grinning Tolg's camp in the nearby cave to brew the elixir. \n\nOnce the elixir is consumed, you should be able to communicate with the ravagers there. With any luck, they should be able to bring you to Skulltaker.\n\nHis mask should bring a hefty reward.", progress = "Dat must be da cursed skull you got dere.", completion = "Dis be an odd mask for a Laughing Skull, to be sure. \n\nJones left dis reward for ya.", objectives = "Use the Laughing Skull elixir to find Skulltaker and claim the Silent Skull.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37997] = { id = 37997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dream of Argus: The Crystal Reborn", description = "With the shards recovered, it is now possible to restore the Dream of Argus. You must seek out the device that Maatun mentions in his journal, which is said to be in a cave overlooking Anguish Fortress.", progress = "You get da crystal put back togetha?", completion = "Astoundin, mon! I'd a never been able ta tell dis was eva broken. \n\nHere's da reward dat Jones left, I'll get dis to im.", objectives = "Locate the crystal reconstruction device and use it to restore the Dream of Argus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38000] = { id = 38000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 001 - Drowned Ruins" }
quests[38001] = { id = 38001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Commander in the Field!", description = "We have been stopped by these new fel orcs, but we will ultimately prevail. Draka and I did manage to get a full scouting group out into the jungle to gather what else we will have to deal with.\n\nYou should seek them out, gain a full understanding of what we face here.", completion = "We have quite a war on our hands. At least we do not lack for targets to strike!", objectives = "Get reports from various scouts in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38003] = { id = 38003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Killed Gaiju" }
