quests[38005] = { id = 38005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "delete me" }
quests[38006] = { id = 38006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "delete me" }
quests[38007] = { id = 38007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "zzOldEMPTY TEST" }
quests[38008] = { id = 38008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Road of Glory", description = "The Horde intends to force us out of Ashran, {name}. We can't let them succeed. March into the Road of Glory and thin their ranks by at least five.", objectives = "Chris Clarkie in Stormshield wants you to kill 5 members of the Horde within the Road of Glory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38009] = { id = 38009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Ruins of Kra'nak" }
quests[38010] = { id = 38010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Max-level Choice Tracker: Tanaan 6.2 - Ruins of Kra'nak" }
quests[38014] = { id = 38014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feasting on the Dragon", description = "You killed their leader, so they came here? Understandable. These creatures crave only one thing - magic - and they can sniff it out from leagues away.\n\nWithout a leader, they will soon wither and die. Our only recourse in the meantime is to put as many as possible down before they take these dragons with them!", progress = "Yes, {name}?", completion = "That will have to do for now.", objectives = "Slay 15 withered in Azurewing Repose.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38015] = { id = 38015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On the Brink", description = "This many withered threaten to wipe our brood out completely!\n\nQuickly, {name}! Crack off a ley crystal and heal any wounded drakes you can find out on the battlefield.\n\nI will do what I can to keep these whelplings safe and healthy.", progress = "Hurry, {name}!", completion = "Well done. I saw the other drakes take to the skies.\n\nAnd look! You found Emmigosa!\n\nIt seems she's taken a shine to you, {name}. I trust you'll keep her safe for now.", objectives = "Use the Radiant Ley Crystal or your healing spells and abilities to resuscitate wounded dragons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38020] = { id = 38020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Temple of Sha'naar" }
quests[38021] = { id = 38021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Max-level Choice Tracker: Tanaan 6.2 - Temple of Sha'naar" }
quests[38022] = { id = 38022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ssault on the Temple of Sha'naar", description = "The Sargerei council continues to work in secret with the warlock, Gul'dan. Up in the hills of Tanaan Jungle, they have converted a once-sacred temple into a den of demonic summoning.\n\nWe must attack them now, before their rituals complete. The longer we delay, the stronger their forces become.", objectives = "Assault the Sargerei forces at the Temple of Sha'naar in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
