quests[38035] = { id = 38035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Royal Summons", progress = "Can we count on you?", completion = "Thank you for your cooperation.", objectives = "Use the Royal Summons and follow Sky Admiral Rogers through the portal to Stormwind Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38036] = { id = 38036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies From the Skies", description = "Are you feeling alright? Say 'ah.'\n\n<Mishka attempts to depress your tongue with a damp twig.>\n\nSorry... we are in desperate need of medical supplies here. The infirmary on the Skyfire was well-stocked, but it's all scattered to the winds now.\n\nAnything you can salvage from the wreck will save lives!", progress = "Did you find anything?", completion = "Just in time! I was about to start bandaging wounds with leaves.", objectives = "Gather 5 Skyfire First Aid Kits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38037] = { id = 38037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cache of Infernals" }
