quests[38042] = { id = 38042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Max-level Choice Tracker: Tanaan 6.2 - Zeth'Gol" }
quests[38043] = { id = 38043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bleeding the Bleeding Hollow" }
quests[38044] = { id = 38044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bleeding the Bleeding Hollow", description = "The Bleeding Hollow provide significant reinforcement to the Iron Horde in Tanaan. From their home in Zeth'Gol they relentlessly pursue our scouts, disrupt our operations, and gather more power for Gul'dan's magic.\n\nWe should consider a direct raid on Zeth'Gol to make them pull back their forces across the valley. This should give us some breathing room... for a time.", progress = "Have you completed the raid, general?", completion = "I already have reports of Bleeding Hollow hunters falling back to Zeth'Gol. This will give us a good edge in the battles to come.", objectives = "Assault the Bleeding Hollow at Zeth'Gol in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38045] = { id = 38045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bleeding the Bleeding Hollow", description = "The Bleeding Hollow provide significant reinforcement to the Iron Horde in Tanaan. From their home in Zeth'Gol they relentlessly pursue our scouts, disrupt our operations, and gather more power for Gul'dan's magic.\n\nWe should consider a direct raid on Zeth'Gol to make them pull back their forces across the valley. This should give us some breathing room... for a time.", progress = "Have you completed the raid yet, general?", completion = "Well done, commander! The Bleeding Hollow are sending their best warriors back to Zeth'Gol to defend it.\n\nThis should give us an advantage, albeit temporarily.", objectives = "Assault the Bleeding Hollow at Zeth'Gol in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38046] = { id = 38046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle At The Iron Front", description = "General, our troops are currently engaged in a conjoined assault at the Iron Front. The fight has been raging for some time now, and casualties are high.\n\nReport to the Iron Front and lend your strength to the war effort. I have no doubt that your presence on the battlefield will inspire the soldiers to victory!", completion = "I'm already hearing reports from The Iron Front that the tide of the battle has turned.\n\nSoon, The Iron Horde will have nowhere to run!", objectives = "Aid the Alliance and Horde assault at The Iron Front in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38047] = { id = 38047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle At The Iron Front", description = "The war against the Iron horde rages on.\n\nNot far from here at The Iron Front, our warriors are engaged in mortal combat with the enemy. They fight tenaciously and with great fury, but the losses have been severe.\n\nGo to The Iron Front and show the enemy that we will not falter in this war.\n\nShow them that we fight as wolves!", completion = "Thanks to your aid, we have gained a foothold at The Iron Front. Soon, Gul'dan and the Iron Horde will have nowhere else to run.", objectives = "Aid the Alliance and Horde assault at The Iron Front in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38051] = { id = 38051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle At The Iron Front" }
quests[38052] = { id = 38052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boarded!", progress = "There will be no peace with those monsters running free.", completion = "Don't worry about the ship - it's just wood and metal.\n\nThe Skyfire lives on as long as we keep fighting.", objectives = "Slay 8 Forsaken Bat-Riders or Forsaken Deathstalkers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38053] = { id = 38053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault and Battery", description = "We need to report our position to the Alliance navy ASAP!\n\nI am building a new transponder to send a distress signal, but I need a battery from the Skyfire's communications console.\n\nYou'll find the console at the top of the ship - I just hope those undead haven't put their creepy, bony fingers on it yet!", progress = "I cannot build a new transponder without that battery!", completion = "NUTS and BOLTS!\n\nPardon my language.\n\nThis thing is almost as dead as the guy you took it from. We need juice, and lots of it. I have an idea...", objectives = "Recover the Transponder Battery from Dread-Rider Malwick.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38054] = { id = 38054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle At The Iron Front" }
quests[38057] = { id = 38057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Legion", completion = "<Though his eyes are open, the soldier does not respond to your presence. An electrical field buzzes around him.>", objectives = "Locate the missing 7th Legion Dragoons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38058] = { id = 38058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lightning Rod", description = "<Overspark's tiny hands move like lightning, affixing coils and tubes to the device before cramming it into a parachute pack.>\n\nPut this on.\n\nJust up the hill you'll find the front half of the Skyfire - and the big nest of storm drakes it crashed into! We can use the energy from those drakes to charge the transponder.\n\nYou'll have to incite them, of course, but the device should draw most of the power.\n\nThe probability of you being electrocuted is well within acceptable parameters!", objectives = "Charge the Transponder by absorbing Storm Drake lightning attacks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38059] = { id = 38059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pins and Needles", description = "Hngghh!\n\nNope, can't stand yet. It's all pins and needles.\n\nSmall fries like this are usually no problem for the 7th, but we weren't prepared for their electrical attacks. Before I knew it, I was trapped in some kind of static field. Couldn't move a muscle until you came along.\n\nMy comrades were carried deeper into the cave. Get 'em out before they become whelp chow!", objectives = "Release 6 7th Legion Dragoons from static fields.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38060] = { id = 38060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signal Boost", description = "The Skyfire's starboard propeller came to rest on the cliffs overlooking our camp - we're gonna use it like a big antenna and push our distress signal so far that even Mekkatorque's alarm clock could pick it up!\n\nUnfortunately, it might attract some unwanted attention.\n\nWe're braced for enemy contact down here at the camp - fire up that signal and be ready to defend the antenna!", completion = "The distress signal got through. We'll be evacuated to Greywatch immediately.\n\nI'm afraid that, for now, you will have to continue on your mission without us. Once we are settled, I will send out recon patrols to see if we can glean the location of the Aegis.\n\nYou must secure the Aegis of Aggramar if we are to drive back the Legion threat!", objectives = "Use the Skyfire Propeller to broadcast a distress signal, then hold out until help arrives.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38061] = { id = 38061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pridelord Meowl" }
