quests[38142] = { id = 38142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archdruid of the Claw", description = "Near the southern edge of our forest you will find Sleeper's Barrow.\n\nThere, Archdruid Koda Steelclaw and her dedicated disciples carry out their sacred duty to observe the Emerald Dream.\n\nFind disciple Rylissa Bearsong in Steelclaw Vale and notify her of the crisis in the Grove of Cenarius.", completion = "The forest already whispers of Malfurion's return. There are few among us who have not heard of his deeds.\n\nThe trees said he also travels with a companion, one named {name}. Are you he?", objectives = "Locate Steelclaw Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38143] = { id = 38143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Awakening the Archdruid", description = "Now, we must focus our efforts on waking Archdruid Steelclaw.\n\nShe and our druid brethren slumber in the barrow dens to the south.\n\nWith the furbolgs quelled, we can pass safely to the entrance.\n\nGo and awaken the Archdruid. I pray to Elune that we are not too late.", completion = "<The Archdruid's deep, shallow breaths rumble across the chamber.>", objectives = "Awaken the Archdruid of the Claw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
